compile.workshop:
variables {
    global:
        0: g
}

rule ("optimized") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Big Message(Event Player, Custom String("3 x"));
        Big Message(Event Player, Custom String("a 3"));
        Big Message(Event Player, Custom String("a {0}", Global.g));
        Big Message(Event Player, Custom String("3 {0} 20", Global.g));
        Big Message(Event Player, Custom String("{0} 3", Global.g));
        Big Message(Event Player, Custom String("3 y"));
        Big Message(Event Player, Custom String("8"));
        Big Message(Event Player, Custom String("{0}", Vector(1, 2, 3)));
        Big Message(Event Player, Custom String("{0}", Hero(Reaper)));
        Big Message(Event Player, Custom String("a"));
        Big Message(Event Player, Custom String("2 5 {0}", Global.g));
        Create HUD Text(Event Player, Custom String("3 x"), Null, Null, Left, 0, Color(White), Color(White), Color(White), Visible To, Default Visibility);
    }
}

//Optimizations disabled
rule ("disabled") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Big Message(Event Player, Custom String("{0} x", Add(1, 2)));
        Big Message(Event Player, Custom String("{0} {1}", Custom String("a"), Add(1, 2)));
        Big Message(Event Player, Custom String("{0} {1}", Custom String("a"), Global.g));
        Big Message(Event Player, Custom String("{0} {1} {2}", Add(1, 2), Global.g, Multiply(4, 5)));
        Big Message(Event Player, Custom String("{0} {1}", Global.g, Add(1, 2)));
        Big Message(Event Player, Custom String("{0}", Custom String("{0} y", Add(1, 2))));
        Big Message(Event Player, Custom String("{0}", Raise To Power(2, 3)));
        Big Message(Event Player, Custom String("{0}", Vector(1, 2, 3)));
        Big Message(Event Player, Custom String("{0}", Hero(Reaper)));
        Big Message(Event Player, Custom String("{0}", If-Then-Else(1, Custom String("a"), Custom String("b"))));
        Big Message(Event Player, Custom String("{0} {1} {2}", Add(1, 1), Add(2, 3), Global.g));
        Create HUD Text(Event Player, Custom String("{0} x", Add(1, 2)), Null, Null, Left, 0, Color(White), Color(White), Color(White), Visible To, Default Visibility);
    }
}

